"""Fixed-price bundles, with all prices and savings in cents."""

from .catalog import product


BUNDLES = {
    'STARTER': {
        'name': 'Starter pack',
        'components': {'MUG': 1, 'TEE': 1},
        'price': 3299,
    },
    'TRAVEL': {
        'name': 'Travel set',
        'components': {'CAP': 1, 'BAG': 1},
        'price': 2099,
    },
}


def apply_bundles(items):
    """Return (bundle counts, remaining items) without changing items.

    Apply each bundle as many times as possible, in code order.
    Items use the cart's uppercase SKUs and nonnegative integer quantities.
    Both returned dictionaries omit zero quantities.
    """
    rest = {sku: qty for sku, qty in items.items() if qty != 0}
    bundles = {}
    for code in sorted(BUNDLES):
        components = BUNDLES[code]['components']
        count = min(rest.get(sku, 0) // qty for sku, qty in components.items())
        if count:
            bundles[code] = count
            for sku, qty in components.items():
                rest[sku] -= qty * count
                if rest[sku] == 0:
                    del rest[sku]
    return bundles, rest


def bundle_savings(code):
    """Return the saving for one bundle in cents; unknown codes raise KeyError."""
    bundle = BUNDLES[code]
    return sum(product(sku)[1] * qty for sku, qty in bundle['components'].items()) - bundle['price']

import unittest
from unittest.mock import patch

from shop.bundles import BUNDLES, apply_bundles, bundle_savings


class BundlesTest(unittest.TestCase):
    def test_fixed_bundles(self):
        self.assertEqual(BUNDLES, {
            'STARTER': {'name': 'Starter pack', 'components': {'MUG': 1, 'TEE': 1}, 'price': 3299},
            'TRAVEL': {'name': 'Travel set', 'components': {'CAP': 1, 'BAG': 1}, 'price': 2099},
        })

    def test_empty_and_zero_items(self):
        self.assertEqual(apply_bundles({}), ({}, {}))
        self.assertEqual(apply_bundles({'MUG': 0, 'TEE': 0}), ({}, {}))

    def test_incomplete_bundles(self):
        items = {'MUG': 2, 'CAP': 1}
        self.assertEqual(apply_bundles(items), ({}, items))

    def test_exact_bundles(self):
        self.assertEqual(apply_bundles({'MUG': 1, 'TEE': 1, 'CAP': 1, 'BAG': 1}),
                         ({'STARTER': 1, 'TRAVEL': 1}, {}))

    def test_repeated_bundles_leftovers_and_input_unchanged(self):
        items = {'MUG': 3, 'TEE': 2, 'CAP': 2, 'BAG': 4}
        original = items.copy()
        self.assertEqual(apply_bundles(items),
                         ({'STARTER': 2, 'TRAVEL': 2}, {'MUG': 1, 'BAG': 2}))
        self.assertEqual(items, original)

    def test_alphabetical_priority_and_component_quantities(self):
        # Reverse insertion order and shared stock make code order observable.
        definitions = {
            'Z': {'name': 'Z', 'components': {'MUG': 1, 'CAP': 1}, 'price': 1000},
            'A': {'name': 'A', 'components': {'MUG': 2, 'TEE': 1}, 'price': 2000},
        }
        with patch.dict(BUNDLES, definitions, clear=True):
            bundles, rest = apply_bundles({'MUG': 5, 'TEE': 3, 'CAP': 2})
            self.assertEqual(bundles, {'A': 2, 'Z': 1})
            self.assertEqual(list(bundles), ['A', 'Z'])
            self.assertEqual(rest, {'TEE': 1, 'CAP': 1})
            self.assertEqual(bundle_savings('A'), 2999)

    def test_savings(self):
        self.assertEqual(bundle_savings('STARTER'), 450)
        self.assertEqual(bundle_savings('TRAVEL'), 399)
        with self.assertRaises(KeyError):
            bundle_savings('UNKNOWN')


if __name__ == '__main__':
    unittest.main()
